<!-- Quizzy design system: exported from the design file ("Quizzy / Style guide" frame). Static: nothing on this page is interactive. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Quizzy · Style guide</title>
<link rel="stylesheet" href="quizzy.css">
<style>
  .sg { max-width: 1100px; margin: 0 auto; padding: 40px 24px 80px; }
  .sg h2 { margin-top: 56px; }
  .sg-row { display: flex; flex-wrap: wrap; gap: 16px; align-items: center; margin: 16px 0; }
  .sg-swatch { width: 150px; border-radius: 16px; overflow: hidden; background: #fff; font-size: 14px; }
  .sg-swatch div:first-child { height: 72px; box-shadow: inset 0 0 0 1px rgb(13 6 64 / 0.12); }
  .sg-swatch div:last-child { padding: 8px 12px; }
  .sg-note { color: var(--c-muted); font-size: 15px; max-width: 720px; }
  .sg-frame { border-radius: 16px; overflow: hidden; margin: 16px 0; }
  .sg-frame .screen { min-height: 0; padding-bottom: 40px; }
  .sg-frame .screen__body { margin-top: 40px; }
  .sg-phone { width: 390px; border-radius: 28px; overflow: hidden; background: var(--c-lavender); box-shadow: 0 20px 60px rgb(13 6 64 / 0.25); }
  .sg-phone .play { min-height: 0; }
</style>
</head>
<body>
<div class="sg">

  <!-- Frame: Header -->
  <span class="logo"><span class="logo__mark">?</span>Quizzy</span>
  <h1 class="mt-2">Style guide</h1>
  <p class="sg-note">Quizzy runs on LED walls and projectors (big screens) and on phones. Bright colors, heavy type, pill buttons. The stylesheet and the font next to this file are the design's assets: use them as they are or adapt them.</p>

  <!-- Frame: Colors -->
  <h2>Colors</h2>
  <div class="sg-row">
    <div class="sg-swatch"><div style="background:#e9e6ff"></div><div>Lavender · page<br>#e9e6ff</div></div>
    <div class="sg-swatch"><div style="background:#2a12c9"></div><div>Blue · ink, primary<br>#2a12c9</div></div>
    <div class="sg-swatch"><div style="background:#ff2e88"></div><div>Pink · accent, danger<br>#ff2e88</div></div>
    <div class="sg-swatch"><div style="background:#0d0640"></div><div>Night · dark screens<br>#0d0640</div></div>
    <div class="sg-swatch"><div style="background:#ffd23f"></div><div>Sun · highlights<br>#ffd23f</div></div>
    <div class="sg-swatch"><div style="background:#00b36b"></div><div>Green · correct<br>#00b36b</div></div>
  </div>

  <!-- Frame: Type -->
  <h2>Typography</h2>
  <p class="sg-note">Inter for everything. Headings use the heaviest weight with tight letter spacing.</p>
  <h1>Heading 1</h1>
  <h2 style="margin-top:0">Heading 2</h2>
  <h3>Heading 3</h3>
  <p>Body text, 18 px. Meta text is smaller and muted: <span class="meta">12 questions · 3 games</span></p>

  <!-- Frame: Buttons -->
  <h2>Buttons</h2>
  <div class="sg-row">
    <a class="btn btn--pink" href="#">Primary</a>
    <a class="btn" href="#">Default</a>
    <a class="btn btn--ghost" href="#">Secondary</a>
    <a class="btn btn--danger" href="#">Destructive</a>
    <a class="btn btn--sm" href="#">Small</a>
    <a class="btn btn--ghost btn--icon" href="#">↑</a>
  </div>
  <div class="sg-row" style="background:var(--c-night);padding:16px;border-radius:16px">
    <a class="btn btn--pink btn--lg" href="#">Big-screen action</a>
    <a class="btn btn--light" href="#">On dark</a>
  </div>

  <!-- Frame: Inputs -->
  <h2>Form controls</h2>
  <div class="card">
    <div class="field">
      <span class="field-label">Text field</span>
      <input class="input" type="text" value="Typed value">
      <span class="field-hint">Hint text explains the field.</span>
    </div>
    <div class="field">
      <span class="field-label">Number field</span>
      <input class="input input--number" type="number" value="3">
    </div>
    <div class="sg-row">
      <span class="checkbox"><input type="checkbox" checked> Checked</span>
      <span class="checkbox"><input type="checkbox"> Unchecked</span>
    </div>
    <div class="errors">Validation errors appear in a pink box above the form.</div>
  </div>

  <!-- Frame: List card -->
  <h2>List card</h2>
  <div class="card question-item">
    <div class="question-item__num">1</div>
    <div>
      <div class="question-item__body">A list item: title text</div>
      <ul class="question-item__options">
        <li>A. Chip</li><li class="is-correct">B. Highlighted chip</li><li>C. Chip</li>
      </ul>
    </div>
    <div class="question-item__actions">
      <div class="buttons"><a class="btn btn--sm" href="#">Action</a><a class="btn btn--sm btn--danger" href="#">Remove</a></div>
    </div>
  </div>

  <!-- Frame: Big screen -->
  <h2>Big screen</h2>
  <p class="sg-note">Full-bleed colored backgrounds with soft shapes, huge type, large tiles. Controls sit in a dark bar at the bottom.</p>
  <div class="sg-frame">
    <section class="cover cover--blue cover--calm">
      <div class="screen">
        <div class="screen__top"><span class="logo screen__logo"><span class="logo__mark">?</span>Quiz",
  "output_tail": "pan>Quizzy</span><span>Name</span></div>
      <div class="play__body play__body--top">
        <div class="play-question__num">Small heading</div>
        <div class="play-question__body">Statement on the phone</div>
        <div class="play-options">
          <div class="play-option"><span class="play-option__letter">A</span><span class="play-option__title">Choice</span></div>
          <div class="play-option is-picked"><span class="play-option__letter">B</span><span class="play-option__title">Selected choice</span></div>
          <div class="play-option"><span class="play-option__letter">C</span><span class="play-option__title">Choice</span></div>
        </div>
        <div class="play-status">Status message</div>
      </div>
    </div>
  </div>

</div>
</body>
</html>
/*
 * Quizzy app styles, loaded after the design's quizzy.css.
 * Keep the design's look: lavender pages, blue ink, pink accents, pill buttons.
 */

/* ---------- Accessibility ---------- */

.btn:focus-visible,
a:focus-visible,
.play-option:focus-visible,
input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--c-pink);
  outline-offset: 3px;
}

/* ---------- Text ---------- */

h1, h2, h3 { overflow-wrap: anywhere; }

/* ---------- Buttons ---------- */

/* Rails' button_to wraps each button in its own form. */
form.button_to { display: inline-flex; margin: 0; }
.buttons form.button_to,
.section-head form.button_to,
.page-head form.button_to { display: contents; }

.btn--block { width: 100%; }
.btn--add { gap: 0.2em; } /* "+ Add option" spaced like plain text */

/* ---------- Moderator layout ---------- */

.admin-header .logo { text-decoration: none; }

.errors > div + div { margin-top: 4px; }

.danger-zone { display: flex; flex-wrap: wrap; gap: 16px; align-items: center; justify-content: space-between; }
.danger-zone p { margin: 0; }

/* ---------- Quiz export / import ---------- */

/* The hidden attribute must win over classes that set display (e.g. .btn). */
[hidden] { display: none !important; }

/* The export JSON (.code-block from the design wraps long lines): focusable, so keyboards can reach and select it. */
.code-block { tab-size: 2; }
.code-block:focus-visible { outline: 3px solid var(--c-pink); outline-offset: 3px; border-radius: 4px; }

/* The design gives textarea.input the text font (a more specific rule than .input--code). */
textarea.input--code { font: 500 15px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace; min-height: 320px; tab-size: 2; }

/* Quiz tiles: each tile is a list item; the title link covers the whole card. */
.quiz-list { list-style: none; padding: 0; margin: 0; }
.quiz-tile { position: relative; margin: 0; }
.quiz-tile h3 { overflow-wrap: anywhere; }
.quiz-tile__link { text-decoration: none; }
.quiz-tile__link::after { content: ""; position: absolute; inset: 0; border-radius: inherit; }
.quiz-tile:hover .quiz-tile__link { color: var(--c-pink); }
.quiz-tile:focus-within { outline: 3px solid var(--c-pink); outline-offset: 3px; }
.quiz-tile__link:focus-visible { outline: none; }

/* Question cards */
.question-list { display: flex; flex-direction: column; gap: 16px; }
.question-list > .question-item { margin: 0; }
.question-item__body { overflow-wrap: anywhere; }
.question-item__option { overflow-wrap: anywhere; }
.question-item__actions form { display: contents; }

@media (max-width: 700px) {
  .question-item { grid-template-columns: auto minmax(0, 1fr); }
  .question-item__actions {
    grid-column: 1 / -1;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
  }
}

/* Question form: option rows */
.option-row__correct { white-space: nowrap; }
/* The label reads "Option 1 is correct" for assistive tech; sighted users see "Correct". */

@media (max-width: 520px) {
  .option-row { gap: 8px; }
}

/* ---------- Preview (player view on a phone) ---------- */

.preview-page { display: flex; flex-direction: column; }
.preview-page .play { flex: 1; width: 100%; min-height: 0; }

.preview-banner .btn { font-size: 14px; padding: 0.5em 1em; }
.preview-banner__actions { display: flex; flex-wrap: wrap; gap: 16px; align-items: center; }

.play-options form { display: contents; }
button.play-option[disabled] { cursor: default; }
button.play-option[disabled]:hover { box-shadow: inset 0 0 0 2px transparent; }
.play-options.is-locked .play-option[disabled] { opacity: 0.55; }
.play-options.is-locked .play-option.is-picked,
.play-options.is-revealed .play-option.is-correct { opacity: 1; }

.play-actions { margin-top: 20px; display: flex; flex-direction: column; gap: 12px; }
.play-actions form { display: contents; }
.play-actions .btn { width: 100%; font-size: 22px; padding: 0.9em; }

.result-card { padding: 40px 24px; }
.result-card__score { font-size: clamp(44px, 14vw, 72px); font-weight: 900; letter-spacing: -0.03em; line-height: 1; margin-bottom: 16px; }

/* ---------- Home ---------- */

.home__links { display: flex; flex-wrap: wrap; gap: 12px; }
